//! Bounded dedicated-route reads and Control Plane self-selection. The caller
//! retains the native operation guard, exact seal and original identity.

use anyhow::{Context, Result, ensure};
use op_plugins::state_plugins::{
    project::ChatMode,
    tched_router::{ConfigPatchInput, ConfigPatchOperation, GetOwnAgentRouteOutput},
};
use serde_json::{Value, json};

pub(crate) const WRITE_CAPABILITY: &str = "cap.software.tched-router.agent.route.self.write@v1";

#[derive(Debug, PartialEq, Eq)]
pub(crate) struct Target {
    pub reference: String,
    pub model: String,
    pub inference_url_prefix: String,
    pub catalog_revision: u64,
}

fn eligible(configured: Option<&str>, session: &str, root: bool, granted: bool) -> bool {
    configured == Some(session) && root && granted
}

/// A current access observation is not a transferable authorization ticket.
/// Both this read and the mutation use the same verified, stored identity.
pub(crate) async fn can_apply(
    engine: &crate::mutation_engine::MutationEngine,
    caller: &crate::tched_router_admission::RouterCaller,
) -> Result<bool> {
    let session = crate::project_dispatch::verified_session(
        engine, &caller.actor, caller.session.as_deref(), caller.genesis.as_deref(),
    ).await?;
    let grants = crate::interceptor::load_capability_grants(&caller.actor);
    if !eligible(
        crate::identity_sled_dispatch::control_plane_chatbot_session_id().as_deref(),
        &session,
        crate::interceptor::principal_in_group(&caller.actor, "$ROOT"),
        grants.contains(WRITE_CAPABILITY),
    ) {
        return Ok(false);
    }
    let context = crate::project_dispatch::current_chat_context(
        engine, &session, &grants.into_iter().collect(),
    ).await?;
    Ok(context.mode == ChatMode::ControlPlane)
}

fn component(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 128
        && value.as_bytes()[0].is_ascii_lowercase()
        && value.bytes().all(|byte| {
            byte.is_ascii_lowercase() || byte.is_ascii_digit() || matches!(byte, b'_' | b'-')
        })
}

fn string<'a>(object: &'a Value, field: &str) -> Result<&'a str> {
    let value = object
        .get(field)
        .and_then(Value::as_str)
        .context("own agent route is incomplete")?;
    ensure!(
        !value.is_empty()
            && value.len() <= 2048
            && value.trim() == value
            && !value.chars().any(char::is_control),
        "own agent route contains an invalid value"
    );
    Ok(value)
}

fn safe_uri(uri: &str) -> Result<()> {
    let url = reqwest::Url::parse(uri)
        .map_err(|_| anyhow::anyhow!("own agent route endpoint is invalid"))?;
    let path = url.path().to_ascii_lowercase();
    ensure!(
        url.scheme() == "https"
            && url.host_str().is_some()
            && url.username().is_empty()
            && url.password().is_none()
            && !uri.contains(['?', '#', '\\'])
            && !path.contains("%2f")
            && !path.contains("%5c"),
        "own agent route endpoint must be credential-free HTTPS"
    );
    Ok(())
}

pub(crate) fn project(mode: ChatMode, config: &Value) -> Result<GetOwnAgentRouteOutput> {
    let alias = crate::chat_mode_routing::dedicated_alias(mode)
        .context("own agent route requires a selected dedicated chat mode")?;
    let agent = config
        .get("agents")
        .and_then(|agents| agents.get(alias))
        .context("own selected agent route is absent")?;
    let reference = string(agent, "model_provider")?;
    let (family, profile) = reference
        .split_once('.')
        .context("own agent provider reference is invalid")?;
    ensure!(
        component(family) && component(profile),
        "own agent provider reference is invalid"
    );
    let provider = config
        .get("providers")
        .and_then(|providers| providers.get("models"))
        .and_then(|models| models.get(family))
        .and_then(|family| family.get(profile))
        .context("own agent provider profile is absent")?;
    let model = string(provider, "model")?;
    let uri = string(provider, "uri")?;
    safe_uri(uri)?;
    Ok(GetOwnAgentRouteOutput {
        mode,
        reference: reference.to_string(),
        model: model.to_string(),
        uri: uri.to_string(),
    })
}

/// Only an already configured, catalog-authoritative dedicated profile may be
/// reused. Shared profiles fail closed rather than changing another agent.
pub(crate) fn prepare(config: &Value, target: &Target) -> Result<(ConfigPatchInput, GetOwnAgentRouteOutput)> {
    ensure!(crate::tched_catalog_binding::valid_reference(&target.reference), "invalid dedicated profile");
    let (family, profile) = target.reference.split_once('.').context("invalid dedicated profile")?;
    let provider = &config["providers"]["models"][family][profile];
    let model = string(provider, "model")?;
    let uri = string(provider, "uri")?;
    ensure!(
        crate::tched_catalog_binding::endpoint_matches(uri, &target.inference_url_prefix)?,
        "dedicated profile endpoint differs from catalog provider authority"
    );
    let agents = config.get("agents").and_then(Value::as_object)
        .context("native agent configuration is absent")?;
    let current = agents.get("control_plane").context("Control Plane agent is absent")?;
    string(current, "model_provider")?;
    // The native Configurable API exposes leaves, not a whole-map property.
    // Retain the shared operation guard and test every existing agent reference.
    ensure!(agents.len() <= 60, "own route agent inventory exceeds atomic patch bound");
    let mut operations = Vec::with_capacity(agents.len() + 4);
    for (alias, agent) in agents {
        ensure!(component(alias), "native agent alias cannot be safely addressed");
        let reference = agent.get("model_provider").and_then(Value::as_str)
            .context("native agent provider reference is absent")?;
        ensure!(
            alias == "control_plane" || !contains_reference(agent, &target.reference),
            "dedicated profile is used by another agent"
        );
        operations.push(ConfigPatchOperation::Test {
            path: format!("/agents/{alias}/model_provider"), value: json!(reference),
        });
    }
    for (section, value) in config.as_object().context("native config is not an object")? {
        ensure!(
            section == "agents" || !contains_reference(value, &target.reference),
            "dedicated profile is used by a shared native route"
        );
    }
    let path = format!("/providers/models/{family}/{profile}");
    operations.extend([
        ConfigPatchOperation::Test { path: format!("{path}/model"), value: json!(model) },
        ConfigPatchOperation::Test { path: format!("{path}/uri"), value: json!(uri) },
        ConfigPatchOperation::Replace { path: format!("{path}/model"), value: json!(target.model) },
        ConfigPatchOperation::Replace {
            path: "/agents/control_plane/model_provider".into(), value: json!(target.reference),
        },
    ]);
    let patch = ConfigPatchInput { operations };
    Ok((patch, GetOwnAgentRouteOutput {
        mode: ChatMode::ControlPlane,
        reference: target.reference.clone(),
        model: target.model.clone(),
        uri: uri.to_string(),
    }))
}

fn contains_reference(value: &Value, reference: &str) -> bool {
    match value {
        Value::String(value) => value == reference,
        Value::Array(values) => values.iter().any(|value| contains_reference(value, reference)),
        Value::Object(values) => values.values().any(|value| contains_reference(value, reference)),
        _ => false,
    }
}

