/**
 * jev-model-router — Jev intent routing for OMP (TypeSafe "intent routing" +
 * "speculative fan-out" patterns).
 *
 * Every user prompt, BEFORE the model starts (before_agent_start):
 *   1. Fan-out: one Jev call answers all turn questions (intent, relevant,
 *      deprecated, already-decided, repeat, plan-first, risky, search, complexity)
 *      against this session's history + the tagged conversation ledger.
 *   2. Route in code (~/.jev-router/src/judge.ts chooseHandler):
 *        intent confidence < 0.5          → CLARIFY   (luna: ask one question)
 *        risky ≥ 0.5                      → CONFIRM   (work model; confirm first)
 *        decided/repeat ≥ 0.8 + ledger hit → RECALL    (luna: quote the earlier decision)
 *        question, complexity < 1         → ANSWER    (luna)
 *        change/investigate               → STANDARD  (sol) or DEEP (astra, complexity ≥ 1.5)
 *        deprecated ≥ 0.8                 → warning first, any handler
 *   3. Hand-off: pi.setModel(handler model) + a note with the handler
 *      instruction, the judgments and the cited ledger passages.
 *
 * Models are openai-codex (ChatGPT plan via OAuth); OMP's own fallbacks
 * (Nous → Devin) still apply. Thinking level stays with OMP (auto → Jev).
 * A model you pick by hand (not luna/sol/astra) is never switched; the note
 * still applies. /jev-judge off disables everything; /jev-route off keeps the
 * note but stops model switching. Fail-open on any error.
 */
import type { ExtensionAPI } from "@oh-my-pi/pi-coding-agent";
import { appendFileSync, existsSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";

const HOME = process.env.HOME ?? "";
const ROOT = process.env.JEV_ROUTER_DIR || `${HOME}/.jev-router`;
const ROUTE_OFF = `${ROOT}/omp-route.off`;
const JUDGE_OFF = `${ROOT}/omp-judge.off`;
const LOG = `${ROOT}/jev-router-live.jsonl`;
const ROUTED = new Set(["openai-codex/gpt-6-luna", "openai-codex/gpt-6.1-sol", "openai-codex/gpt-6-astra"]);

const key = (m: any) => (m ? `${m.provider}/${m.id}` : "");
const short = (k: string) => k.split("/").pop() ?? k;
const pct = (v: number) => `${Math.round(v * 100)}%`;

function promptText(prompt: unknown): string {
  if (typeof prompt === "string") return prompt;
  if (Array.isArray(prompt)) return prompt.map((b: any) => (b?.type === "text" ? b.text : "")).join("\n");
  return "";
}

export default function jevIntentRouter(pi: ExtensionAPI) {
  pi.setLabel?.("Jev Intent Router");
  let mod: any = null;
  let last = "jev: waiting for first prompt";

  const sessionsDir = `${HOME}/.omp/agent/sessions`;
  function newestSession(): string | null {
    let best: string | null = null, bestM = 0;
    try {
      for (const d of readdirSync(sessionsDir)) {
        let names: string[] = [];
        try { names = readdirSync(`${sessionsDir}/${d}`); } catch { continue; }
        for (const n of names) {
          if (!n.endsWith(".jsonl")) continue;
          const m = statSync(`${sessionsDir}/${d}/${n}`).mtimeMs;
          if (m > bestM) { bestM = m; best = `${sessionsDir}/${d}/${n}`; }
        }
      }
    } catch { /* no sessions */ }
    return best;
  }
  function log(rec: Record<string, unknown>) {
    try { appendFileSync(LOG, JSON.stringify({ ts: new Date().toISOString(), host: "omp", via: "omp", ...rec }) + "\n", { mode: 0o600 }); }
    catch { /* best-effort */ }
  }
  const status = (ctx: any, text: string) => { last = text; ctx.ui?.setStatus?.("jev-route", text); };

  pi.on("session_start", async (_e: unknown, ctx: any) => {
    status(ctx, existsSync(JUDGE_OFF) ? "jev off" : existsSync(ROUTE_OFF) ? "jev judge on · routing off" : "jev routing on");
  });

  pi.on("before_agent_start", async (event: { prompt?: unknown }, ctx: any) => {
    if (existsSync(JUDGE_OFF)) return;
    const text = promptText(event.prompt).trim();
    if (!text) return;
    const t0 = Date.now();
    try {
      mod ??= await import(`${ROOT}/src/judge.ts`);
      // History: this session + relevant ledger passages.
      const file = ctx.sessionManager?.getSessionFile?.() ?? newestSession();
      let history: any = { user: [], assistant: [] };
      try { if (file) history = mod.historyFromOmpSession(readFileSync(file, "utf8")); } catch { /* none */ }
      const lastUser = history.user[history.user.length - 1];
      if (lastUser && text.startsWith(lastUser.replace(/ …$/, "").slice(0, 200))) history.user.pop(); // never judge against itself
      try { history.past = await mod.searchCollection(text, 3, 6000); } catch { history.past = []; }

      const j = await mod.judgeTurn(text, 10_000, history);
      if (!j) { status(ctx, "jev: unavailable, turn unchanged"); log({ kind: "turn-route", failOpen: true }); return; }
      const { handler, model: wanted } = mod.chooseHandler(j);

      // Model hand-off (only between luna/sol/astra; a hand-picked model stays).
      const current = key(ctx.model);
      let served = current;
      if (wanted && !existsSync(ROUTE_OFF) && (!current || ROUTED.has(current)) && wanted !== current) {
        const list: any[] = ctx.models?.list?.() ?? ctx.modelRegistry?.getAvailable?.() ?? [];
        const m = list.find((x) => key(x) === wanted);
        if (m) { await pi.setModel(m); served = wanted; }
      }

      const content = mod.handlerInstruction(handler) + "\n" + j.note;
      status(ctx, `jev ${handler.toUpperCase()} → ${short(served)} · ${j.intent ?? "?"} ${pct(j.intentConfidence)}` +
        `${j.deprecated >= 0.8 ? " · deprecated" : ""}${j.alreadyDecided >= 0.8 ? " · decided" : ""}${j.repeat >= 0.8 ? " · repeat" : ""}` +
        `${j.risky >= 0.5 ? " · risky" : ""} · ${Date.now() - t0}ms`);
      log({ kind: "turn-route", handler, chosenModel: served, tier: handler, confidence: j.intentConfidence,
        intent: j.intent, complexity: j.complexity, deprecated: j.deprecated, alreadyDecided: j.alreadyDecided,
        repeat: j.repeat, risky: j.risky, relevant: j.relevant, passages: j.past.map((p: any) => p.source),
        failOpen: false, ms: Date.now() - t0 });
      return { message: { customType: "jev-turn-judgment", content, display: true } };
    } catch (e: any) {
      status(ctx, "jev: error, turn unchanged");
      log({ kind: "turn-route", failOpen: true, error: String(e?.message ?? e).slice(0, 200) });
      return;
    }
  });

  const toggle = (file: string, name: string) => ({
    description: `${name}: on | off | status`,
    handler: async (args: string, ctx: any) => {
      const a = (args || "").trim().toLowerCase();
      if (a === "off") writeFileSync(file, "off\n");
      else if (a === "on") rmSync(file, { force: true });
      const state = existsSync(file) ? "off" : "on";
      ctx.ui?.notify?.(`${name} ${state}. Last: ${last}`, "info");
    },
  });
  pi.registerCommand?.("jev-judge", toggle(JUDGE_OFF, "Jev per-turn judgment + routing"));
  pi.registerCommand?.("jev-route", toggle(ROUTE_OFF, "Jev model switching"));
}
/**
 * omp-jev-tools — native omp extension: TypeSafe (Jev) judgment tools.
 *
 * Five tools that make OMP more powerful with Jev:
 *   jev_judge   — batched typed questions (fan-out): one call, many judgments
 *   jev_route   — confidence-gated routing: pick a handler + act/threshold advice
 *   jev_rerank  — token efficiency: select which candidates enter the context
 *   jev_verify  — claim-vs-evidence citation check
 *   jev_models  — list models available to the key
 *
 * Install: omp plugin install omp-jev-tools  (or link this directory)
 * Env: TYPESAFE_API_KEY (required), TYPESAFE_MODEL (default jev-latest)
 */
import type { ExtensionAPI } from "@oh-my-pi/pi-coding-agent";
import { systemOne, withRetry, DEFAULT_MODEL, getApiKey, type Question } from "./client.js";

export default function jevTools(pi: ExtensionAPI) {
  const z = pi.zod;
  pi.setLabel("Jev Tools");
  // -------------------------------------------------------------------
  // session_start — light nudge so the model remembers the tools exist
  // (Jev nudge: set JEV_NUDGE=0 in env to disable)
  // -------------------------------------------------------------------
  pi.on("session_start", async (_event, ctx) => {
    if (process.env.JEV_NUDGE === "0" || !getApiKey()) return;
    ctx.ui.notify("Jev tools ready: jev_route / jev_rerank / jev_verify (+ /jev command)", "info");
    showJevStatus(ctx);
  });

  // -------------------------------------------------------------------
  // Local addition: show OMP's own Jev (TypeSafe) activity in the status
  // line — calls per purpose this session, read from the session log.
  // -------------------------------------------------------------------
  const sessionsDir = `${process.env.HOME}/.omp/agent/sessions`;
  function newestSession(): string | null {
    const fs = require("node:fs") as typeof import("node:fs");
    let best: string | null = null, bestM = 0;
    try {
      for (const d of fs.readdirSync(sessionsDir)) {
        const dir = `${sessionsDir}/${d}`;
        let names: string[] = [];
        try { names = fs.readdirSync(dir); } catch { continue; }
        for (const n of names) {
          if (!n.endsWith(".jsonl")) continue;
          const m = fs.statSync(`${dir}/${n}`).mtimeMs;
          if (m > bestM) { bestM = m; best = `${dir}/${n}`; }
        }
      }
    } catch { /* no sessions */ }
    return best;
  }
  function showJevStatus(ctx: any): void {
    try {
      const fs = require("node:fs") as typeof import("node:fs");
      const f = newestSession();
      if (!f) return;
      const counts: Record<string, number> = {};
      let cost = 0;
      for (const line of fs.readFileSync(f, "utf8").split("\n")) {
        if (!line.includes('"provider":"typesafe"')) continue;
        try {
          const r = JSON.parse(line);
          if (r.type !== "model_usage") continue;
          counts[r.purpose ?? "?"] = (counts[r.purpose ?? "?"] ?? 0) + 1;
          cost += Number(r.usage?.cost?.total ?? 0);
        } catch { /* partial line */ }
      }
      const total = Object.values(counts).reduce((a, b) => a + b, 0);
      const parts = Object.entries(counts).map(([p, n]) => `${p} ${n}`).join(" · ");
      ctx.ui.setStatus?.("jev", total ? `jev ${total} (${parts}) $${cost.toFixed(4)}` : "jev ready");
    } catch { /* status is best-effort */ }
  }
  for (const ev of ["turn_end", "agent_end", "message_end"]) {
    try { pi.on(ev as any, async (_e: unknown, ctx: any) => showJevStatus(ctx)); } catch { /* event not supported */ }
  }

  // -------------------------------------------------------------------
  // jev_judge — the core primitive: one request, a map of typed questions
  // -------------------------------------------------------------------
  const questionSchema = z.object({
    type: z.enum(["noul", "choice", "score"]),
    instructions: z.unknown().describe("The judgment: a string, or JSON structure (object/array) for richer prompts."),
    criteria: z.unknown().optional().describe("Noul: {true,false}. Choice: option->description map. Score: ordered level descriptions array."),
  });

  // jev_judge removed locally: OMP's built-in judge() covers it.

  // -------------------------------------------------------------------
  // jev_route — confidence-gated routing (patterns/confidence-routing)
  // -------------------------------------------------------------------
  pi.registerTool({
    name: "jev_route",
    label: "Jev Route",
    description:
      "Confidence-gated routing: pick one handler from a defined set via Jev and get an explicit ACT / CONFIRM / ESCALATE recommendation derived from the choice's confidence. High confidence (>0.85) → act autonomously; moderate (0.6-0.85) → verify intent first; low (<0.6) → escalate to a human or reasoning model. Use for intent routing, dispatch decisions, and anywhere the answer tells you WHAT and confidence tells you WHETHER to act.",
    parameters: z.object({
      state: z.unknown().describe("The request/situation to route."),
      instructions: z.string().describe("What the router decides (e.g. 'Which handler should process this request?')."),
      options: z.record(z.string(), z.string()).describe("Map of option id -> description of what this handler covers. At least 2."),
      model: z.string().optional().describe(`TypeSafe model (default ${DEFAULT_MODEL}).`),
    }),
    async execute(_id, params, signal) {
      const criteria: Record<string, string | null> = {};
      for (const [k, v] of Object.entries(params.options)) criteria[k] = v;
      const res = await withRetry((s) => systemOne(
        { state: params.state, model: params.model, questions: { route: { type: "choice", instructions: params.instructions, criteria } } },
        s,
      ), { signal });
      const a = res.answers.route;
      if (a.type !== "choice") throw new Error("unexpected answer type from Jev route");
      const gate = a.confidence > 0.85 ? "ACT" : a.confidence >= 0.6 ? "CONFIRM" : "ESCALATE";
      const gateAdvice =
        gate === "ACT" ? "safe to act autonomously on this routing" :
        gate === "CONFIRM" ? "verify intent before acting" :
        "route to a human or reasoning model first";
      const text = [
        `route=${a.choice}`,
        `confidence=${a.confidence} → ${gate}`,
        `probabilities: ${Object.entries(a.probabilities).sort((x, y) => y[1] - x[1]).map(([k, v]) => `${k}=${v}`).join(" ")}`,
        `gate: ${gateAdvice}`,
        `tokens(in/out)=${res.usage.input_tokens}/${res.usage.output_tokens}`,
      ].join("\n");
      return { content: [{ type: "text", text }], details: { route: a.choice, confidence: a.confidence, gate, response: res } };
    },
  });

  // -------------------------------------------------------------------
  // jev_rerank — token efficiency (cookbooks/rerank_typesafe)
  // -------------------------------------------------------------------
  pi.registerTool({
    name: "jev_rerank",
    label: "Jev Rerank",
    description:
      "Token efficiency: given a query and a list of candidate texts (grep results, search hits, doc chunks), one TypeSafe call scores every candidate's relevance to the query; code then keeps only the top-k. Use before feeding results into the model context to cut tokens drastically. Returns ranked ids with relevance scores and the recommended keep-list.",
    parameters: z.object({
      query: z.string().describe("What the caller is looking for (plain language)."),
      candidates: z.array(z.object({ id: z.string(), text: z.string() })).describe("Candidates to rank. id is caller's identifier (path, row id, url)."),
      top_k: z.number().optional().describe("How many to keep (default 5, or all if fewer)."),
      model: z.string().optional().describe(`TypeSafe model (default ${DEFAULT_MODEL}).`),
    }),
    async execute(_id, params, signal) {
      const topK = params.top_k ?? 5;
      const questions: Record<string, Question> = {};
      for (const c of params.candidates) {
        questions[c.id] = {
          type: "score",
          instructions: "How well does this candidate answer or address the query?",
          criteria: [
            "Irrelevant: has nothing to do with the query.",
            "Partially relevant: touches the query topic but does not answer it.",
            "Relevant: directly addresses the query.",
            "Best match: the single best answer to the query among the candidates.",
          ],
        };
      }
      // One state for all questions: the model needs both query and every candidate
      // to judge relative relevance, and all scores come back in a single call.
      const state = {
        query: params.query,
        candidates: params.candidates.map((c) => ({ id: c.id, text: c.text.slice(0, 2000) })),
      };
      const res = await withRetry((s) => systemOne({ state, model: params.model, questions }, s), { signal });
      const scored = params.candidates
        .map((c) => {
          const a = res.answers[c.id];
          return a && a.type === "score"
            ? { id: c.id, relevance: a.score / 3, confidence: a.confidence }
            : { id: c.id, relevance: 0, confidence: 0 };
        })
        .sort((x, y) => y.relevance - x.relevance);
      const keep = scored.slice(0, topK);
      const text = [
        ...scored.map((s, i) => `${i + 1}. ${s.id} relevance=${s.relevance.toFixed(2)}${i < topK ? " *" : ""}`),
        `keep ${keep.length}/${params.candidates.length}: ${keep.map((k) => k.id).join(", ")}`,
        `tokens(in/out)=${res.usage.input_tokens}/${res.usage.output_tokens}`,
      ].join("\n");
      return { content: [{ type: "text", text }], details: { ranked: scored, keep: keep.map((k) => k.id) } };
    },
  });

  // -------------------------------------------------------------------
  // jev_verify — claim vs evidence (cookbooks/citation_check)
  // -------------------------------------------------------------------
  pi.registerTool({
    name: "jev_verify",
    label: "Jev Verify",
    description:
      "Verify a claim against its cited evidence in one TypeSafe request: a Choice picks whether the source supports the claim (supports / contradicts / insufficient), a Noul checks whether the quote appears verbatim, and a Score rates how misleading it would be to keep the claim. Confidence flags uncertain verdicts for human review. Use to double-check citations, hallucinated quotes, and fact-grounding.",
    parameters: z.object({
      claim: z.string().describe("The claim or statement being made."),
      evidence: z.string().describe("The source text it cites (document excerpt, search result, file content)."),
      quote: z.string().optional().describe("Optional verbatim quote claimed to come from the evidence."),
      model: z.string().optional().describe(`TypeSafe model (default ${DEFAULT_MODEL}).`),
    }),
    async execute(_id, params, signal) {
      const state = { claim: params.claim, evidence: params.evidence, quote: params.quote ?? null };
      const questions: Record<string, Question> = {
        verdict: {
          type: "choice",
          instructions: "Does the evidence support the claim?",
          criteria: {
            supports: "The evidence clearly establishes the claim is true.",
            contradicts: "The evidence shows the claim is false.",
            insufficient: "The evidence does not settle the claim either way.",
          },
        },
        verbatim: {
          type: "noul",
          instructions: params.quote
            ? "Does this exact quote appear in the evidence text?"
            : "Does the claim quote the evidence verbatim anywhere?",
          criteria: { true: "The quoted words appear in the evidence.", false: "The quote does not appear in the evidence." },
        },
        misleading: {
          type: "score",
          instructions: "If the claim is kept as stated, how misleading would it be?",
          criteria: [
            "Not misleading: accurate and well-supported.",
            "Slightly misleading: technically true but easy to misread.",
            "Misleading: the evidence points another way.",
            "Seriously misleading: asserts the opposite of what the evidence shows.",
          ],
        },
      };
      const res = await withRetry((s) => systemOne({ state, model: params.model, questions }, s), { signal });
      const a = res.answers;
      if (a.verdict.type !== "choice") throw new Error("unexpected answer type from Jev verify");
      const verbatimNoul = a.verbatim.type === "noul" ? a.verbatim.noul : undefined;
      const misScore = a.misleading.type === "score" ? a.misleading.score : undefined;
      const flag = a.verdict.confidence < 0.6 ? " — low confidence, review" : "";
      const text = [
        `verdict=${a.verdict.choice}${flag}`,
        `verbatim=${verbatimNoul?.toFixed(2)}`,
        `misleading=${misScore?.toFixed(1)}/3`,
        `confidence=${a.verdict.confidence}`,
        `tokens(in/out)=${res.usage.input_tokens}/${res.usage.output_tokens}`,
      ].join("\n");
      return { content: [{ type: "text", text }], details: { verdict: a.verdict.choice, confidence: a.verdict.confidence, verbatim: verbatimNoul, misleading: misScore, response: res } };
    },
  });

  // -------------------------------------------------------------------
  // jev_models
  // -------------------------------------------------------------------
  // jev_models removed locally: OMP's built-in judge() covers it.

  // -------------------------------------------------------------------
  // Slash command: /jev — quick judgment from the prompt line
  // -------------------------------------------------------------------
  pi.registerCommand("jev", {
    description: "Ask Jev a quick yes/no question: /jev is <question>? <text>",
    handler: async (args, ctx) => {
      const m = args.match(/^\s*(is\s+.+?\?)\s*([\s\S]+)$/i);
      const question = m?.[1] ?? "Is this true?";
      const state = m?.[2] ?? args;
      if (!getApiKey()) {
        ctx.ui.notify("TYPESAFE_API_KEY not set — add it to ~/.omp/agent/.env", "error");
        return;
      }
      const res = await withRetry((s) => systemOne({ state, questions: { q: { type: "noul", instructions: question } } }, s));
      const val = res.answers.q.type === "noul" ? res.answers.q.noul : 0;
      pi.sendMessage({
        customType: "jev-judgment",
        content: `${question} → ${Math.round(val * 100)}% yes (jev: ${res.model})`,
        display: true,
        attribution: "assistant",
      }, { triggerTurn: false });
    },
  });
}

