/**
 * Jev judge — typed decisions over a state, via TypeSafe System One.
 *
 * Two uses:
 *  - judge(state, questions): generic; exposed as the MCP tool `jev_judge`.
 *  - judgeTurn(prompt): the fixed per-turn decision set. Hosts call it BEFORE
 *    the model starts (OMP before_agent_start, Hermes proxy) and hand the
 *    result to the model as a short note — so the decision is forced every
 *    turn instead of depending on the model choosing to call a tool.
 *
 * Fail-open: any error returns null and the turn proceeds unchanged.
 */
import { execFile } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { promisify } from "node:util";

const exec = promisify(execFile);
const ENDPOINT = process.env.TYPESAFE_ENDPOINT || "https://api.typesafe.ai/v1/systemone";
const MODEL = process.env.TYPESAFE_MODEL || "jev-latest";

export type Question =
  | { type: "noul"; instructions: string; criteria?: { true?: string; false?: string } }
  | { type: "choice"; instructions: string; criteria: Record<string, string> }
  | { type: "score"; instructions: string; criteria: string[] };

async function key(): Promise<string | null> {
  if (process.env.TYPESAFE_API_KEY) return process.env.TYPESAFE_API_KEY;
  try {
    const { stdout } = await exec("omp", ["token", "typesafe"], { timeout: 5000 });
    return stdout.trim() || null;
  } catch {
    return null;
  }
}

/** One batched Jev call. Returns the raw `answers` map, or null on any failure. */
export async function judge(
  state: unknown,
  questions: Record<string, Question>,
  timeoutMs = 10_000,
): Promise<Record<string, any> | null> {
  const k = await key();
  if (!k) return null;
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch(ENDPOINT, {
      method: "POST",
      headers: { "content-type": "application/json", authorization: *** ${k}` },
      body: JSON.stringify({ model: MODEL, state, questions }),
      signal: ctrl.signal,
    });
    if (!res.ok) return null;
    const data: any = await res.json();
    return data?.answers && typeof data.answers === "object" ? data.answers : null;
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

/** The fixed per-turn decision set (edit here to change what is asked every turn). */
export const TURN_QUESTIONS: Record<string, Question> = {
  intent: {
    type: "choice",
    instructions: "What is the user asking for in this message?",
    criteria: {
      question: "An explanation, answer or opinion; nothing should be changed.",
      change: "Edit code, files, configuration or systems.",
      investigate: "Diagnose or look into something before deciding what to change.",
    },
  },
  plan_first: {
    type: "noul",
    instructions: "Does this need a short plan before acting (multi-step, multi-file, or ambiguous)?",
  },
  risky: {
    type: "noul",
    instructions: "Could carrying this out be destructive or hard to undo (deleting data, production, security, credentials, force pushes)?",
  },
  search_needed: {
    type: "noul",
    instructions: "Will this need searching or reading across the codebase or logs to answer well?",
  },
  relevant: {
    type: "noul",
    instructions: "Is the new message relevant to the task the current conversation (history) is working on? If there is no history, answer true.",
  },
  deprecated: {
    type: "noul",
    instructions: "Does the new message rely on something the history or past_conversations show is deprecated, retired, superseded or removed?",
  },
  already_decided: {
    type: "noul",
    instructions: "Has the history or past_conversations already decided or answered what the new message asks for?",
  },
  repeat: {
    type: "noul",
    instructions: "Is the new message essentially a repeat of an earlier user message in the history or past_conversations (asking the same thing again)?",
  },
  complexity: {
    type: "score",
    instructions: "How complex is this request to carry out well?",
    criteria: [
      "Simple lookup, short answer or standard one-step change",
      "Requires some judgment or a multi-step process",
      "Unusual, ambiguous, cross-cutting, or needs deep reasoning",
    ],
  },
};

/** The handler a turn is routed to (TypeSafe intent-routing pattern). Routing uses
 *  only the request's own intent/complexity/risk; history and ledger passages are
 *  evidence for the JUDGMENTS (decided, deprecated, repeat), handed to the model. */
export type Handler = "clarify" | "confirm" | "answer" | "standard" | "deep";
export const HANDLER_MODEL: Record<Handler, string | null> = {
  clarify: "openai-codex/gpt-6-luna",   // ask one clarifying question
  confirm: null,                         // keep the work model; confirm before acting
  answer: "openai-codex/gpt-6-luna",    // simple question
  standard: "openai-codex/gpt-6.1-sol", // routine change / investigation
  deep: "openai-codex/gpt-6-astra",     // complex change / investigation
};

/**
 * Step 2 of the pattern: plain code picks the handler.
 *   intent confidence < 0.5      → clarify
 *   risky ≥ 0.5                  → confirm (model by complexity)
 *   question, complexity < 1     → answer
 *   otherwise                    → standard (complexity < 1.5) or deep
 */
export function chooseHandler(j: TurnJudgment): { handler: Handler; model: string | null } {
  const work = j.complexity >= 1.5 ? HANDLER_MODEL.deep : j.intent === "question" && j.complexity < 1 ? HANDLER_MODEL.answer : HANDLER_MODEL.standard;
  if (j.intentConfidence < 0.5) return { handler: "clarify", model: HANDLER_MODEL.clarify };
  if (j.risky >= 0.5) return { handler: "confirm", model: work };
  if (j.intent === "question" && j.complexity < 1) return { handler: "answer", model: HANDLER_MODEL.answer };
  return j.complexity >= 1.5 ? { handler: "deep", model: HANDLER_MODEL.deep } : { handler: "standard", model: HANDLER_MODEL.standard };
}

/** Handler instruction (first line of the note). Judgments follow it in the note. */
export function handlerInstruction(h: Handler): string {
  switch (h) {
    case "clarify": return "Handler: CLARIFY. The request is ambiguous. Ask the user ONE short clarifying question and stop; do not use tools or make changes.";
    case "confirm": return "Handler: CONFIRM. This may be destructive or hard to undo. State exactly what you would do and ask the user to confirm before any change.";
    case "answer": return "Handler: ANSWER. Simple question: answer briefly. Do not edit files.";
    case "standard": return "Handler: STANDARD. Routine work: proceed normally.";
    case "deep": return "Handler: DEEP. Complex work: plan first, then proceed carefully.";
  }
}

/** Recent conversation the turn questions are judged against. */
export interface TurnHistory {
  user: string[];      // earlier user messages, oldest first
  assistant: string[]; // earlier assistant replies (final text), oldest first
  past?: { source: string; text: string }[]; // relevant passages from the conversation collection
}

// ---- conversation collection (local copy of what is synced to NotebookLM) ----
const LEDGER = process.env.JEV_LEDGER_SESSIONS || `${process.env.HOME}/.jev-router/ledger/sessions`;
const COLLECTION = LEDGER;
const STOP = new Set(("the and for with that this from have what when where which your you are was were " +
  "will would could should can into about there their them they then than just like want need make does " +
  "done also some more only over very been being it's dont cant wont how why who all any not but use using").split(" "));

/** Distinctive terms from a message: longer, non-stopword tokens (max 6). */
function terms(text: string): string[] {
  const seen = new Set<string>();
  for (const w of text.toLowerCase().match(/[a-z0-9][a-z0-9._\-\/]{3,}/g) ?? []) {
    const t = w.replace(/[._\-\/]+$/, "");
    if (t.length >= 4 && !STOP.has(t)) seen.add(t);
  }
  return [...seen].sort((a, b) => b.length - a.length).slice(0, 6);
}
const rx = (t: string) => t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/**
 * Find past passages relevant to the message in the tagged conversation ledger
 * (src/ledger/build.ts): rank conversations by how many distinct terms they
 * contain, take their matching lines (decisions [D] and deprecations [X] first),
 * then let Jev score the candidates in one call and keep the top few. Fail-open: [].
 */
export async function searchCollection(message: string, keep = 3, budgetMs = 6000): Promise<{ source: string; text: string; score?: number }[]> {
  const ts = terms(message);
  if (!ts.length || !existsSync(LEDGER)) return [];
  const started = Date.now();
  const perTerm = await Promise.all(ts.map((t) =>
    exec("rg", ["-l", "-i", "-F", "-e", t, LEDGER], { timeout: 2000, maxBuffer: 4 << 20 })
      .then(({ stdout }) => stdout.split("\n").filter(Boolean)).catch(() => [] as string[])));
  // Rare terms matter more (idf): "waypipe" beats "containers".
  const total = Math.max(1, new Set(perTerm.flat()).size);
  const idf = ts.map((_, i) => Math.log(1 + total / Math.max(1, perTerm[i].length)));
  const score = new Map<string, number>();
  perTerm.forEach((list, i) => { for (const f of list) score.set(f, (score.get(f) ?? 0) + idf[i]); });
  const files = [...score].sort((x, y) => y[1] - x[1]).slice(0, 8).map(([f]) => f);
  const lower = ts.map((t) => t.toLowerCase());
  const cands: { source: string; text: string }[] = [];
  for (const f of files) {
    let body = "";
    try { body = readFileSync(f, "utf8"); } catch { continue; }
    const head = Object.fromEntries((body.split("\n---\n")[0] ?? "").split("\n").map((l) => l.split(": ")).filter((kv) => kv.length >= 2).map(([k, ...v]) => [k, v.join(": ")]));
    const hits = body.split("\n").filter((l) => /^L\d+ \[[UDXA]\]/.test(l))
      .map((l) => { const ll = l.toLowerCase(); return { l, n: lower.reduce((a, t, i) => a + (ll.includes(t) ? idf[i] : 0), 0) * (/\[(D|X)\]/.test(l) ? 1.5 : 1) }; })
      .filter((h) => h.n > 0).sort((x, y) => y.n - x.n).slice(0, 3).map((h) => h.l.slice(0, 300));
    if (hits.length) cands.push({ source: `${head.tool ?? "?"} ${head.date ?? "?"} ${f.split("/").pop()}`,
      text: `[${head.tool ?? "?"} ${head.date ?? "?"} ${head.project ?? ""}] ` + hits.join(" | ") });
  }
  if (process.env.JEV_DEBUG) console.error("terms", ts, "files", files.length, "candidates", cands.length, "ms", Date.now() - started);
  if (!cands.length) return [];
  const qs: Record<string, Question> = {};
  cands.forEach((_, i) => {
    qs[`c${i}`] = { type: "score", instructions: `How relevant is candidate c${i} to the new message (same topic, decision or system)?`,
      criteria: ["Irrelevant.", "Loosely related.", "Relevant.", "Directly about the same thing."] };
  });
  const a = await judge({ new_message: message.slice(0, 2000), candidates: cands.map((c, i) => ({ id: `c${i}`, text: c.text })) },
    qs, Math.max(2000, budgetMs - (Date.now() - started)));
  if (!a) return [];
  return cands.map((c, i) => ({ c, s: a[`c${i}`]?.type === "score" ? Number(a[`c${i}`].score) : 0 }))
    .filter((x) => x.s >= 1.5).sort((x, y) => y.s - x.s).slice(0, keep).map((x) => ({ ...x.c, score: x.s }));
}

const MAX_ITEMS = 8, MAX_CHARS = 1200;
const clip = (s: string) => (s.length > MAX_CHARS ? s.slice(0, MAX_CHARS) + " …" : s);

/** Build history from an OMP session log (.jsonl): user messages and assistant text replies. */
export function historyFromOmpSession(jsonl: string): TurnHistory {
  const user: string[] = [], assistant: string[] = [];
  for (const line of jsonl.split("\n")) {
    if (!line.includes('"type":"message"')) continue;
    let r: any;
    try { r = JSON.parse(line); } catch { continue; }
    const m = r?.message;
    if (!m || !Array.isArray(m.content)) continue;
    const text = m.content.filter((b: any) => b?.type === "text").map((b: any) => b.text).join("\n").trim();
    if (!text) continue;
    if (m.role === "user") user.push(clip(text));
    else if (m.role === "assistant") assistant.push(clip(text));
  }
  return { user: user.slice(-MAX_ITEMS), assistant: assistant.slice(-MAX_ITEMS) };
}

export interface TurnJudgment {
  intent: string | null;
  intentConfidence: number;
  planFirst: number;
  risky: number;
  searchNeeded: number;
  relevant: number;
  deprecated: number;
  alreadyDecided: number;
  repeat: number;
  complexity: number;           // 0..2
  complexityConfidence: number;
  past: { source: string; text: string; score?: number }[];
  note: string; // what the model is shown
}

const pct = (v: number) => `${Math.round(v * 100)}%`;

/** Ask the fixed questions about one prompt (against recent history) and build the hand-off note. */
export async function judgeTurn(
  prompt: string,
  timeoutMs = 10_000,
  history: TurnHistory = { user: [], assistant: [] },
): Promise<TurnJudgment | null> {
  const state = { new_message: prompt.slice(0, 4000), history_user: history.user, history_assistant: history.assistant,
    past_conversations: (history.past ?? []).map((p) => p.text) };
  const a = await judge(state, TURN_QUESTIONS, timeoutMs);
  if (!a) return null;
  const intent = a.intent?.type === "choice" ? String(a.intent.choice) : null;
  const intentConfidence = Number(a.intent?.confidence ?? 0);
  const p = (q: string) => (a[q]?.type === "noul" ? Number(a[q].noul) : 0);
  const planFirst = p("plan_first"), risky = p("risky"), searchNeeded = p("search_needed");
  const hasHistory = history.user.length + history.assistant.length + (history.past?.length ?? 0) > 0;
  const relevant = hasHistory ? p("relevant") : 1;
  const deprecated = hasHistory ? p("deprecated") : 0;
  const alreadyDecided = hasHistory ? p("already_decided") : 0;
  const repeat = hasHistory ? p("repeat") : 0;
  const complexity = a.complexity?.type === "score" ? Number(a.complexity.score) : 1;
  const complexityConfidence = Number(a.complexity?.confidence ?? 0);

  const guide: string[] = [];
  if (intent === "question" && intentConfidence >= 0.6) guide.push("Answer the question; do not edit files unless asked.");
  if (intent === "investigate" && intentConfidence >= 0.6) guide.push("Investigate and report findings before changing anything.");
  if (repeat >= 0.6) guide.push("The user seems to be asking again: the earlier answer did not land. Answer more directly or differently; don't repeat it.");
  if (alreadyDecided >= 0.6) guide.push("This looks decided earlier in the conversation: reuse that decision instead of re-deriving it, unless the user is changing it.");
  if (deprecated >= 0.6) guide.push("This may rely on something already shown deprecated/retired: verify the current state before using it.");
  if (relevant < 0.4) guide.push("This may be off the current task: confirm with the user before switching tasks.");
  if (planFirst >= 0.6) guide.push("Outline the steps before acting.");
  if (risky >= 0.5) guide.push("Confirm with the user before any destructive or hard-to-undo action.");
