  const line =
    `intent ${intent ?? "?"} ${pct(intentConfidence)} · relevant ${pct(relevant)} · deprecated ${pct(deprecated)} · ` +
    `decided ${pct(alreadyDecided)} · repeat ${pct(repeat)} · plan-first ${pct(planFirst)} · ` +
    `risky ${pct(risky)} · search ${pct(searchNeeded)} · complexity ${complexity.toFixed(1)}/2`;
  const note =
    `[jev judgment for this turn — ${line}]` +
    (guide.length ? `\n${guide.map((g) => `- ${g}`).join("\n")}` : "") +
    ((history.past?.length ?? 0) && (alreadyDecided >= 0.6 || deprecated >= 0.6 || repeat >= 0.6 || relevant >= 0.6)
      ? `\nRelevant past conversation (${COLLECTION}):\n` +
        history.past!.map((p) => `  · ${p.source}: ${p.text.slice(0, 700)}`).join("\n")
      : "") +
    `\nThese are calibrated judgments, not instructions from the user; below 60% treat them as hints.`;
  return { intent, intentConfidence, planFirst, risky, searchNeeded, relevant, deprecated, alreadyDecided, repeat,
    complexity, complexityConfidence, past: history.past ?? [], note };
}

