#!/usr/bin/env -S node --experimental-strip-types
/**
 * Minimal MCP server over stdio (JSON-RPC 2.0, newline-delimited). Exposes one
 * tool: context_and_route. No external dependencies — implements just enough of
 * the Model Context Protocol handshake and tools/call to be usable by any MCP
 * client (Pi, Kiro, Claude, etc.).
 */
import { createInterface } from "node:readline";
import { contextAndRoute } from "../route.ts";

const PROTOCOL_VERSION = "2024-11-05";

const TOOL = {
  name: "context_and_route",
  description:
    "Unified context-aware router. Gathers workspace state (git diff, last exit code), " +
    "classifies difficulty via Jev, and returns the chosen model, thinking depth, ordered " +
    "fallback chain, route persona, and trimmed payload. Never collapses to a single default; " +
    "holds to the medium tier on low confidence; fails open when the classifier is unavailable. " +
    "DeepSeek is always rejected.",
  inputSchema: {
    type: "object",
    properties: {
      request: { type: "string", description: "The user request / prompt text to route." },
      host: { type: "string", enum: ["omp", "hermes"], description: "Calling agent; selects which provider logins are eligible (default omp)." },
      cwd: { type: "string", description: "Working directory to inspect for git state." },
      lastExitCode: { type: "number", description: "Exit code of the last command (0 if none)." },
      lastStderr: { type: "string", description: "Stderr of the last command, if any." },
      activeFile: { type: "string", description: "Path of the active file, if any." },
    },
    required: ["request"],
  },
};

function send(msg: unknown): void {
  process.stdout.write(JSON.stringify(msg) + "\n");
}

function reply(id: unknown, result: unknown): void {
  send({ jsonrpc: "2.0", id, result });
}
function fail(id: unknown, code: number, message: string): void {
  send({ jsonrpc: "2.0", id, error: { code, message } });
}

const rl = createInterface({ input: process.stdin });
rl.on("line", async (line) => {
  const text = line.trim();
  if (!text) return;
  let msg: any;
  try {
    msg = JSON.parse(text);
  } catch {
    return; // ignore non-JSON noise
  }
  const { id, method, params } = msg;
  try {
    switch (method) {
      case "initialize":
        reply(id, {
          protocolVersion: PROTOCOL_VERSION,
          capabilities: { tools: {} },
          serverInfo: { name: "jev-router", version: "0.1.0" },
        });
        return;
      case "notifications/initialized":
        return; // notification, no reply
      case "tools/list":
        reply(id, { tools: [TOOL] });
        return;
      case "tools/call": {
        if (params?.name !== "context_and_route") {
          fail(id, -32601, `unknown tool: ${params?.name}`);
          return;
        }
        const args = params.arguments ?? {};
        if (typeof args.request !== "string" || !args.request) {
          fail(id, -32602, "request (string) is required");
          return;
        }
        const routed = await contextAndRoute({
          request: args.request,
          host: args.host === "hermes" || (args.host === undefined && process.env.JEV_ROUTER_HOST === "hermes") ? "hermes" : "omp",
          cwd: args.cwd,
          lastExitCode: args.lastExitCode,
          lastStderr: args.lastStderr,
          activeFile: args.activeFile ?? null,
        });
        reply(id, {
          content: [{ type: "text", text: JSON.stringify(routed, null, 2) }],
          structuredContent: routed,
          isError: false,
        });
        return;
      }
      default:
        if (id !== undefined) fail(id, -32601, `method not found: ${method}`);
    }
  } catch (e: any) {
    if (id !== undefined) fail(id, -32603, e?.message ?? "internal error");
  }
});

process.stderr.write("jev-router MCP server ready on stdio\n");
/**
 * TypeSafe (System One / Jev) API client for omp-jev-tools.
 * Zero dependencies — plain fetch against https://api.typesafe.ai.
 *
 * Env:
 *   TYPESAFE_API_KEY  (required) — Bearer key
 *   TYPESAFE_API_URL  (optional) — override base URL
 *   TYPESAFE_MODEL    (optional) — default model, else "jev-latest"
 */

export interface NoulQuestion {
  type: "noul";
  instructions: unknown;
  criteria?: { true?: string; false?: string };
}
export interface ChoiceQuestion {
  type: "choice";
  instructions: unknown;
  criteria: Record<string, string | null>;
}
export interface ScoreQuestion {
  type: "score";
  instructions: unknown;
  criteria: unknown[];
}
export type Question = NoulQuestion | ChoiceQuestion | ScoreQuestion;

export interface NoulAnswer {
  type: "noul";
  noul: number;
}
export interface ChoiceAnswer {
  type: "choice";
  choice: string;
  probabilities: Record<string, number>;
  confidence: number;
}
export interface ScoreAnswer {
  type: "score";
  score: number;
  legend: Record<string, string>;
  probabilities: Record<string, number>;
  confidence: number;
}
export type Answer = NoulAnswer | ChoiceAnswer | ScoreAnswer;

export interface SystemOneResponse {
  model: string;
  answers: Record<string, Answer>;
  usage: { input_tokens: number; output_tokens: number };
}

export const API_URL = process.env.TYPESAFE_API_URL || "https://api.typesafe.ai";
export const DEFAULT_MODEL = process.env.TYPESAFE_MODEL || "jev-latest";

export function getApiKey(): string | undefined {
  return process.env.TYPESAFE_API_KEY || undefined;
}

export class TypeSafeApiError extends Error {
  status: number;
  body: unknown;
  constructor(status: number, body: unknown) {
    const detail =
      body && typeof body === "object" && "error" in body
        ? String((body as { error?: { message?: string } }).error?.message ?? JSON.stringify(body))
        : typeof body === "string" && body
          ? body
          : JSON.stringify(body);
    super(`TypeSafe API ${status}: ${detail}`);
    this.status = status;
    this.body = body;
  }
}

async function parseBody(res: Response): Promise<unknown> {
  const text = await res.text();
  try {
    return text ? JSON.parse(text) : {};
  } catch {
    return text;
  }
}

/** POST /v1/systemone — one request, a map of typed questions. */
export async function systemOne(
  args: { state: unknown; model?: string; questions: Record<string, Question> },
  signal?: AbortSignal,
): Promise<SystemOneResponse> {
  const key = getApiKey();
  if (!key) throw new Error("TYPESAFE_API_KEY is not set (add it to ~/.omp/agent/.env or the shell environment)");
  const res = await fetch(`${API_URL}/v1/systemone`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: *** ${key}` },
    body: JSON.stringify({
      state: args.state,
      model: args.model || DEFAULT_MODEL,
      questions: args.questions,
    }),
    signal,
  });
  const body = await parseBody(res);
  if (!res.ok) throw new TypeSafeApiError(res.status, body);
  return body as SystemOneResponse;
}

/** GET /v1/models */
export async function listModels(signal?: AbortSignal): Promise<{ models: { name: string; description: string; release_date: string }[] }> {
  const key = getApiKey();
  if (!key) throw new Error("TYPESAFE_API_KEY is not set");
  const res = await fetch(`${API_URL}/v1/models`, {
    headers: { Authorization: *** ${key}` },
    signal,
  });
  const body = await parseBody(res);
  if (!res.ok) throw new TypeSafeApiError(res.status, body);
  return body as { models: { name: string; description: string; release_date: string }[] };
}
/** Retry wrapper: exponential backoff on 429/529/connection errors (SDK default policy). */
export async function withRetry<T>(fn: (signal?: AbortSignal) => Promise<T>, opts: { attempts?: number; baseMs?: number; signal?: AbortSignal } = {}): Promise<T> {
  const attempts = opts.attempts ?? 3;
  const baseMs = opts.baseMs ?? 500;
  let lastErr: unknown;
  for (let i = 0; i < attempts; i++) {
    if (opts.signal?.aborted) throw new Error("aborted");
    try {
      return await fn(opts.signal);
    } catch (err) {
      lastErr = err;
      const retriable =
        err instanceof TypeSafeApiError
          ? err.status === 429 || err.status === 529
          : err instanceof Error && (err.name === "TypeError" || err.message.includes("ECONNRESET"));
      if (!retriable || i === attempts - 1) throw err;
      const { promise, resolve } = Promise.withResolvers<void>();
      setTimeout(resolve, baseMs * 2 ** i);
      await promise;
    }
  }
  throw lastErr;
}

